(async () => {
  const { readFileSync } = await import('node:fs');
  const csvPath = process.env.CSV_PATH;
  if (!csvPath) {
    throw new Error('Missing required env var CSV_PATH');
  }
  const data = readFileSync(csvPath, 'utf8');
  globalThis._csvData = data;
})();

(async () => {
  const { parse } = await import('csv-parse');
  const csvData = globalThis._csvData;
  if (typeof csvData !== 'string') {
    throw new Error('CSV data not prepared');
  }
  const records = await new Promise((resolve, reject) => {
    parse(csvData, { skip_empty_lines: true }, (err, output) => {
      if (err) reject(err);
      else resolve(output);
    });
  });
  if (!Array.isArray(records) || records.length === 0) {
    globalThis._markdown = '';
    return;
  }
  const header = records[0];
  const separator = header.map(() => '---');
  const lines = [];
  lines.push('| ' + header.join(' | ') + ' |');
  lines.push('| ' + separator.join(' | ') + ' |');
  for (let i = 1; i < records.length; i++) {
    const row = records[i];
    lines.push('| ' + row.join(' | ') + ' |');
  }
  globalThis._markdown = lines.join('\n');
})();
